
 create role anon;create role authenticated;create schema auth;create schema pharmflow_auth_private;create schema supabase_migrations;
 create table supabase_migrations.schema_migrations(version text primary key,statements text[],name text,created_by text,idempotency_key text unique,rollback text[]);
 insert into supabase_migrations.schema_migrations(version,statements,name) values('20261031010759',array['-- synthetic prior migration'],'receiving_extra_batch_correction');
 create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('test.uid',true),'')::uuid$$;
 create function is_system_owner() returns boolean language sql stable as $$select coalesce(current_setting('test.owner',true),'no')='yes'$$;
 create function pharmflow_auth_private.password_change_complete() returns boolean language sql stable as $$select coalesce(current_setting('test.valid',true),'yes')='yes'$$;
 create table pharmacies(id uuid primary key,active boolean not null default true,status text not null default 'active' check(status in ('active','suspended')));
 create table pharmacy_members(pharmacy_id uuid references pharmacies(id),user_id uuid,active boolean,role text check(role in ('admin','staff')),unique(pharmacy_id,user_id));
 create table pharmflow_pharmacy_permissions_v1(pharmacy_id uuid primary key references pharmacies(id),receiving text not null default 'DISABLED' check(receiving in ('FULL','READ_ONLY','DISABLED')),expiry text not null default 'DISABLED' check(expiry in ('FULL','READ_ONLY','DISABLED')),data_access text not null default 'READ_ONLY',revision bigint not null default 1,updated_by uuid,updated_at timestamptz default now());
 create table pharmflow_permission_audit_v1(id uuid default gen_random_uuid(),pharmacy_id uuid,actor uuid,before_value jsonb not null,after_value jsonb not null,created_at timestamptz default now());
 create function pharmflow_auth_private.seed_permissions() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$begin insert into pharmflow_pharmacy_permissions_v1(pharmacy_id,receiving,expiry,data_access) values(new.id,'DISABLED','DISABLED','READ_ONLY');return new;end$$;
 create trigger pharmflow_seed_permissions after insert on pharmacies for each row execute function pharmflow_auth_private.seed_permissions();
 insert into pharmacies values('11111111-1111-4111-8111-111111111111',true,'active'),('22222222-2222-4222-8222-222222222222',true,'active');
 insert into pharmacy_members values('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true,'admin');
 update pharmflow_pharmacy_permissions_v1 set receiving='FULL',expiry='FULL' where pharmacy_id='11111111-1111-4111-8111-111111111111';
 create table receiving_synthetic(pharmacy_id uuid,quantity int);create table expiry_synthetic(pharmacy_id uuid,quantity int);
 insert into receiving_synthetic values('11111111-1111-4111-8111-111111111111',17);insert into expiry_synthetic values('11111111-1111-4111-8111-111111111111',23);
 alter table receiving_synthetic enable row level security;alter table expiry_synthetic enable row level security;
 create policy receiving_scope on receiving_synthetic for select to authenticated using(pharmacy_id='11111111-1111-4111-8111-111111111111');
 create policy expiry_scope on expiry_synthetic for select to authenticated using(pharmacy_id='11111111-1111-4111-8111-111111111111');
 grant select on receiving_synthetic,expiry_synthetic to authenticated;
 alter table pharmflow_pharmacy_permissions_v1 enable row level security;alter table pharmflow_permission_audit_v1 enable row level security;
 grant select on pharmflow_pharmacy_permissions_v1,pharmflow_permission_audit_v1 to authenticated;
 set test.uid='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
GRANT USAGE ON SCHEMA public,auth TO authenticated,anon;
GRANT SELECT ON pharmacy_members TO authenticated;
DROP POLICY receiving_scope ON receiving_synthetic;
DROP POLICY expiry_scope ON expiry_synthetic;
CREATE POLICY receiving_scope ON receiving_synthetic FOR SELECT TO authenticated USING(pharmacy_id IN (SELECT pharmacy_id FROM pharmacy_members WHERE user_id=auth.uid() AND active));
CREATE POLICY expiry_scope ON expiry_synthetic FOR SELECT TO authenticated USING(pharmacy_id IN (SELECT pharmacy_id FROM pharmacy_members WHERE user_id=auth.uid() AND active));
